{
  "critique": [
    {
      "design": "r2A",
      "good": "费用项目保持单行，三档职级易于横向比较。住宿限额、票种和交通限额都清楚，行高也能让每一行读成一个整体。",
      "problems": "经理的一线城市住宿单元格把“含早餐”拆成“含”和“早餐”；其他城市住宿的“10%”单独占一行，视觉上较零散。总监列的几处说明也换行较多。",
      "cause": "经理列为120px，可用文字宽度99px，不足以让相关词组在当前行完整排下；总监列130px仍需将较长的限制条件分行。"
    },
    {
      "design": "r2B",
      "good": "行标题和表头保持完整，三档职级仍有清晰的比较关系。经理列略宽，内容分布与r2A相近。",
      "problems": "高铁行因总监的条件多出一行，“上”单独落在末行，破坏词语完整性，也让这一行过高。整表因此比r2A高23px。",
      "cause": "总监列从130px缩至128px，使“程 4 小时以上”无法按r2A的方式排入第二行；经理列增加的2px没有带来相应改善。"
    },
    {
      "design": "r2C",
      "good": "行标题完整，整体高度与r2A相同；总监的高铁条件保持两行，没有r2B的孤字。",
      "problems": "普通员工和经理的一线城市住宿单元格都把“含早餐”拆开，两个并列单元格同时出现不自然的断行；经理列的“10%”仍独占一行。",
      "cause": "普通员工列增至118px后，第一行恰好容下“含”，却容不下完整的“含早餐”；经理列缩至119px也无法容下完整词组。"
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "r3A",
      "widths": [113, 116, 118, 132],
      "change": "以r2A为基础，将经理列的2px移给总监列，保留普通员工列较自然的早餐断行，并尝试改善总监列较长的限制条件。"
    },
    {
      "name": "r3B",
      "widths": [110, 116, 120, 133],
      "change": "略收行标题列，把3px分给总监列；检验行标题是否仍能保持单行，以及总监列是否能更自然地排下长条件。"
    },
    {
      "name": "r3C",
      "widths": [113, 116, 125, 125],
      "change": "尝试把更多空间分给经理列，观察能否改善早餐和上浮比例的断行，同时检验总监列缩窄后的代价。"
    }
  ]
}
